sealed class ClientException: kotlin.Exception() {
    
    /**
     * 网络不通、超时：稍后重试，离线时用缓存。
     */
    class Network(
        
        override val `message`: kotlin.String
        ) : ClientException() {
    }
    
    /**
     * 没有登录，或登录已失效（刷新令牌被吊销、被重复使用、设备被远程下线）：回到登录页。
     */
    class SignedOut(
        ) : ClientException() {
        override val message
            get() = ""
    }
    
    /**
     * 客户端版本太老：提示升级。
     */
    class UpgradeRequired(
        ) : ClientException() {
        override val message
            get() = ""
    }
    
    /**
     * 账号被冻结（风控、运维，4.6）：提示联系客服。登录状态保留，解冻后接着用。
     */
    class AccountFrozen(
        ) : ClientException() {
        override val message
            get() = ""
    }
    
    /**
     * 服务端返回的错误。`code` 是 [`ErrorCode`] 的字符串形式（not_found、conflict、invalid……）。
     */
    class Api(
        
        val `status`: kotlin.UShort, 
        
        val `code`: kotlin.String, 
        
        override val `message`: kotlin.String, 
        
        val `retryAfterSecs`: kotlin.ULong?
        ) : ClientException() {
    }
    
    /**
     * 响应解析失败（服务端和客户端版本不匹配）。
     */
    class Decode(
        
        override val `message`: kotlin.String
        ) : ClientException() {
    }
    
    /**
     * 本地缓存读写失败。
     */
    class Cache(
        
        override val `message`: kotlin.String
        ) : ClientException() {
    }
    
    /**
     * 消息里有像密码、key 的内容（11.6），没有发出去：提示用户存进保险箱，消息里换成引用
     * （`detect_secrets`、`save_secret_from_message`），或者用户确认后带 `allow_secrets` 重发。
     */
    class ContainsSecrets(
        
        val `count`: kotlin.UInt
        ) : ClientException() {
        override val message
            get() = "count=${ `count` }"
    }
    
    /**
     * 调用方传的参数不对（id 格式、枚举取值）。
     */
    class InvalidArgument(
        
        override val `message`: kotlin.String
        ) : ClientException() {
    }
    
    /**
     * client-core 内部错误（后台任务异常退出）。
     */
    class Internal(
        
        override val `message`: kotlin.String
        ) : ClientException() {
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ClientException> {
        override fun lift(error_buf: RustBuffer.ByValue): ClientException = FfiConverterTypeClientError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeClientError : FfiConverterRustBuffer<ClientException> {
    override fun read(buf: ByteBuffer): ClientException {
        

        return when(buf.getInt()) {
            1 -> ClientException.Network(
                FfiConverterString.read(buf),
                )
            2 -> ClientException.SignedOut()
            3 -> ClientException.UpgradeRequired()
            4 -> ClientException.AccountFrozen()
            5 -> ClientException.Api(
                FfiConverterUShort.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterOptionalULong.read(buf),
                )
            6 -> ClientException.Decode(
                FfiConverterString.read(buf),
                )
            7 -> ClientException.Cache(
                FfiConverterString.read(buf),
                )
            8 -> ClientException.ContainsSecrets(
                FfiConverterUInt.read(buf),
                )
            9 -> ClientException.InvalidArgument(
                FfiConverterString.read(buf),
                )
            10 -> ClientException.Internal(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ClientException): ULong {
        return when(value) {
            is ClientException.Network -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is ClientException.SignedOut -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ClientException.UpgradeRequired -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ClientException.AccountFrozen -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ClientException.Api -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUShort.allocationSize(value.`status`)
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`message`)
                + FfiConverterOptionalULong.allocationSize(value.`retryAfterSecs`)
            )
            is ClientException.Decode -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is ClientException.Cache -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is ClientException.ContainsSecrets -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.`count`)
            )
            is ClientException.InvalidArgument -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is ClientException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
        }
    }

    override fun write(value: ClientException, buf: ByteBuffer) {
        when(value) {
            is ClientException.Network -> {
                buf.putInt(1)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is ClientException.SignedOut -> {
                buf.putInt(2)
                Unit
            }
            is ClientException.UpgradeRequired -> {
                buf.putInt(3)
                Unit
            }
            is ClientException.AccountFrozen -> {
                buf.putInt(4)
                Unit
            }
            is ClientException.Api -> {
                buf.putInt(5)
                FfiConverterUShort.write(value.`status`, buf)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`message`, buf)
                FfiConverterOptionalULong.write(value.`retryAfterSecs`, buf)
                Unit
            }
            is ClientException.Decode -> {
                buf.putInt(6)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is ClientException.Cache -> {
                buf.putInt(7)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is ClientException.ContainsSecrets -> {
                buf.putInt(8)
                FfiConverterUInt.write(value.`count`, buf)
                Unit
            }
            is ClientException.InvalidArgument -> {
                buf.putInt(9)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is ClientException.Internal -> {
                buf.putInt(10)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





