/**
 * 连接状态，给界面显示“连接中 / 已连接 / 重连中”。
 */
sealed class StreamStatus {
    
    object Connecting : StreamStatus()
    
    
    object Live : StreamStatus()
    
    
    /**
     * 断开了，`retry_in_ms` 毫秒后重连。
     */
    data class Reconnecting(
        val `retryInMs`: kotlin.ULong) : StreamStatus()
        
    {
        

        companion object
    }
    
    /**
     * 登录失效，事件流停止；回到登录页。
     */
    object SignedOut : StreamStatus()
    
    
    /**
     * 实例不存在或不属于当前用户，事件流停止。
     */
    object NotFound : StreamStatus()
    
    
    /**
     * 账号被冻结（4.6），事件流停止；提示联系客服。
     */
    object AccountFrozen : StreamStatus()
    
    
    object Stopped : StreamStatus()
    
    

    

    
    


    companion object
}

